const lang=document.documentElement.lang==='en'?1:0,L=(vi,en)=>lang?en:vi,c=HVAC_TOOL_CONFIGS[document.body.dataset.tool],E=HVACTools,root=document.getElementById('tool-root'),fmt=(v,n=2)=>Number.isFinite(v)?new Intl.NumberFormat(lang?'en-US':'vi-VN',{maximumFractionDigits:n,...(v!==0&&Math.abs(v)<.01?{maximumSignificantDigits:3}:{})}).format(v):'—',esc=s=>String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
