function update(){try{sync();const x=read();if(c.key==='insulation')x.candidateSizes=window.HVACInsulationPresets?.sizes(x);if(['fan','pump'].includes(c.key))checkRows();result={x,r:E[c.key](x,rows)};document.getElementById('tool-error').hidden=true;render(result.x,result.r);document.getElementById('tool-print').disabled=false;document.getElementById('tool-preview').disabled=false;}catch(e){result=null;const error=document.getElementById('tool-error');error.hidden=false;const messages={grilleInputs:L('Kiểm tra loại miệng, số lượng nguyên và tỷ lệ diện tích hữu dụng.','Check type, integer count and free-area ratio.'),fittingInputs:L('Kiểm tra lưu lượng, kích thước, số lượng nguyên và hệ số K không âm.','Check flow, dimensions, integer quantity and nonnegative K.'),reservePressure:L('Để giữ nước dự trữ, áp suất nạp nước lạnh phải lớn hơn áp suất nạp khí.','To hold an initial water reserve, cold fill pressure must exceed gas pre-charge.'),rows:L('Thêm ít nhất một đoạn trên tuyến.','Add at least one path section.'),branchFlow:L('Lưu lượng đoạn không được lớn hơn lưu lượng qua quạt/bơm.','Section flow cannot exceed total fan/pump flow.'),temperatureOrder:L('Nhiệt độ cao nhất phải lớn hơn nhiệt độ thấp nhất.','Highest temperature must exceed lowest temperature.'),pressureOrder:L('Áp suất phải thỏa: nạp khí ≤ nạp nước lạnh < lớn nhất.','Pressures must satisfy: pre-charge ≤ cold fill < maximum.'),expansionRange:L('Tỷ lệ giãn nở không hợp lệ trong khoảng nhiệt độ này.','Invalid expansion fraction over this temperature range.')};error.textContent=e.message.startsWith('input:')?L('Kiểm tra thông số: ','Check input: ')+fields.find(f=>f.key===e.message.split(':')[1]).label[lang]:messages[e.message]||L('Nhập số hợp lệ trong phạm vi cho phép ở các ô được đánh dấu.','Enter valid numbers within the allowed ranges in the marked fields.');document.getElementById('tool-result').innerHTML='';document.getElementById('tool-links').innerHTML='';document.getElementById('tool-print').disabled=true;document.getElementById('tool-preview').disabled=true;}savePath();}
form.addEventListener('input',event=>{const el=event.target;if(c.key==='insulation')window.HVACInsulationPresets?.input(el);if(c.key==='ventilation'&&el.id==='t-ez')document.getElementById('t-ezConfig').value='custom';if(c.key==='grille'&&['t-width','t-height'].includes(el.id))document.getElementById('t-quick').value='custom';if(el.id==='t-flow'&&previousFlow!==null&&el.value.trim()!==''){const newFlow=Number(el.value);rows.forEach(row=>{if(row.flow===previousFlow)row.flow=newFlow;});rowEditor();}if(el.id==='t-flow'&&el.value.trim()!==''&&Number.isFinite(Number(el.value))&&Number(el.value)>0)previousFlow=Number(el.value);if(el.dataset.row!==undefined){rows[Number(el.dataset.row)][el.dataset.key]=el.dataset.key==='name'?el.value:Number(el.value);}update();});form.addEventListener('change',event=>{const el=event.target;if(c.key==='insulation')window.HVACInsulationPresets?.change(el);if(c.key==='ventilation'&&el.id==='t-ezConfig'){const preset=window.HVAC_EZ_ROWS?.find(v=>v.key===el.value);if(preset)document.getElementById('t-ez').value=preset.value;}if(c.key==='grille'&&el.id==='t-kind'){document.getElementById('t-quick').value='custom';grilleQuick();}if(c.key==='grille'&&el.id==='t-quick'&&el.value!=='custom'){const [a,b]=el.value.split('x');document.getElementById('t-width').value=a;document.getElementById('t-height').value=b;}if(c.key==='fittings'&&el.id==='t-medium'){const water=el.value==='water';for(const [k,v] of Object.entries({flow:water?10:2400,flowUnit:'m3h',a:water?65:400,b:water?65:300,shape:water?'round':'rect'}))document.getElementById('t-'+k).value=v;}if(el.dataset.key==='shape'){rows[Number(el.dataset.row)].shape=el.value;rowEditor();}update();});form.addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){rows.splice(Number(b.dataset.remove),1);rowEditor();update();}});
if(rows.length){document.getElementById('row-add').onclick=()=>{const x=read(false);rows.push(c.key==='fan'?{name:L('Đoạn mới','New section'),shape:'rect',flow:x.flow,a:500,b:300,length:0,k:0,device:0}:{name:L('Đoạn mới','New section'),flow:x.flow,d:65,length:0,k:0,device:0});rowEditor();update();};rowEditor();}
document.getElementById('tool-reset').onclick=()=>{flowUnit=null;for(const f of fields)document.getElementById('t-'+f.key).value=f.value;rows=JSON.parse(JSON.stringify(initialRows));importedIds=[];rowEditor();document.getElementById('transfer-notice').hidden=true;update();previousFlow=document.getElementById('t-flow')?Number(document.getElementById('t-flow').value):null;};
let importedIds=[];const pathKey='hvacstudio:path:'+lang+':'+c.key;function savePath(){if(!['fan','pump'].includes(c.key))return;try{sessionStorage.setItem(pathKey,JSON.stringify({values:Object.fromEntries(fields.map(f=>[f.key,document.getElementById('t-'+f.key).value])),rows,ids:importedIds.slice(-100)}));}catch(e){}}if(['fan','pump'].includes(c.key)){try{const draft=JSON.parse(sessionStorage.getItem(pathKey));if(draft&&Array.isArray(draft.rows)&&draft.rows.length<=300){for(const f of fields){const v=draft.values?.[f.key];if(v!==undefined&&(f.options?f.options.some(o=>o.value===v):Number.isFinite(Number(v))))document.getElementById('t-'+f.key).value=v;}if(draft.rows.every(v=>typeof v.name==='string'&&['flow','length','k','device',...(c.key==='fan'?['a','b']:['d'])].every(k=>Number.isFinite(v[k]))))rows=draft.rows;importedIds=Array.isArray(draft.ids)?draft.ids.filter(v=>typeof v==='string'):[];rowEditor();}}catch(e){}}
const params=new URLSearchParams(location.search);let transferred=false;for(const key of ['flow','load','sensible','unit','system','count','temp','rough','rho','mu','medium','shape','a','b','flowUnit']){const f=fields.find(f=>f.key===key);if(f&&params.has(key)&&!params.has('import_fitting')){const value=params.get(key),valid=f.options?f.options.some(o=>o.value===value):value.trim()!==''&&Number.isFinite(Number(value))&&Number(value)>=f.min&&Number(value)<=f.max;if(valid){document.getElementById('t-'+key).value=value;transferred=true;}}}if(transferred){if(rows.length&&!params.has('import_fitting')){for(const k of ['a','b','d','length'])if(params.has(k)){const v=Number(params.get(k));if(Number.isFinite(v)&&v>0&&v<=100000)rows.forEach((row,i)=>{if(k!=='length'||i===0)row[k]=v;});}if(['rect','round'].includes(params.get('shape'))&&c.key==='fan')rows.forEach(row=>row.shape=params.get('shape'));}if(params.has('flow')&&!params.has('import_fitting'))rows.forEach(v=>v.flow=Number(document.getElementById('t-flow')?.value||v.flow));rowEditor();const n=document.getElementById('transfer-notice');n.hidden=false;n.textContent=L('Đã nhận thông số từ công cụ liên kết. Kiểm tra các thông số còn lại trước khi áp dụng kết quả.','Inputs received from a linked tool. Review the remaining parameters before applying the result.');}
if(params.has('import_fitting')&&['fan','pump'].includes(c.key)){const id=params.get('fitting_id'),q=Number(params.get('flow')),k=Number(params.get('k')),a=Number(params.get('a')),b=Number(params.get('b')),d=Number(params.get('d')),shape=params.get('shape');const valid=id&&id.length<100&&q>0&&q<=1e7&&k>=0&&k<=1e6&&(c.key==='fan'?['round','rect'].includes(shape)&&a>0&&a<=10000&&b>0&&b<=10000:d>0&&d<=10000);if(valid){const n=document.getElementById('transfer-notice');n.hidden=false;if(!importedIds.includes(id)&&rows.length<300){const name=(params.get('fitting_name')+(params.get('source')?' · '+params.get('source'):'')).slice(0,80);rows.push(c.key==='fan'?{name,flow:q,shape,a,b,length:0,k,device:0}:{name,flow:q,d,length:0,k,device:0});importedIds.push(id);if(q>Number(document.getElementById('t-flow').value))document.getElementById('t-flow').value=q;rowEditor();n.textContent=L('Đã thêm phụ kiện vào tuyến hiện tại. Kiểm tra khối lượng riêng/nhiệt độ, các đoạn và tổn thất thiết bị mẫu trước khi chọn quạt/bơm.','Fitting added to the current path. Review density/temperature, sections and sample equipment losses before sizing.');}else n.textContent=L('Phụ kiện này đã có trong tuyến; không thêm trùng khi tải lại trang.','This fitting is already in the path; reloading does not add it again.');}}
